;---------------------------------------------------------------------------------------------------
; ReadMap ($2DAD6)
; Called from: Isr_GPT_IC1
;---------------------------------------------------------------------------------------------------
ReadMap:
        BRCLR   >ADCSTAT_L,Z,#$01,ReadMap                ; bit 0: CCF0: ADC conversion 0 complete
        LDAA    >RJURR0_L,Z
        STAA    >MapRaw,Z
        LDAB    >EngineRpm,Z
        CMPB    #$6E
        BCC     L2DB06
        CMPB    #$13
        BCS     L2DB06
        LDAB    >ThrottleAboveClosed,Z
        CMPB    >MapRationalThrottleMax
        BCC     L2DB06
        CMPA    >MapRawHighLimit
        BCC     L2DB0C
        CMPA    >MapRawLowLimit
        BCS     L2DB0C
L2DB06:
        BRCLR   >SensorFaultFlags,Z,#$20,L2DB12          ; bit 5: MAP sensor fault (P0106, P0107, P0108 or P1297 set): limp MAP in use
L2DB0C:
        JSR     LimpMapCalc
        BRA     L2DB1E
L2DB12:
        LDAB    >MapRawStart,Z
        ABA
        RORA
        JSR     RawScaleF4
L2DB1E:
        BRCLR   >Options0337,#$08,L2DB30                 ; bit 3: selects a branch in ReadMap
        TAB
        ADDA    >ReadMapA81,Z
        RORA
        STAB    >ReadMapA81,Z
L2DB30:
        STAA    >Map,Z
        JSR     RawScale69
        STAA    >ReadMapA82,Z
        LDAB    >Map,Z
        LDAA    <Baro,Z
        SBA
        BCC     L2DB48
        CLRA
L2DB48:
        STAA    >ManifoldVacuum,Z
        RTS

;---------------------------------------------------------------------------------------------------
; EquipmentDetect ($2DB4E)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
EquipmentDetect:
        BRSET   >EquipmentFlags,Z,#$80,L2DBA8            ; bit 7: A/C fitted (EquipmentDetect)
        BRCLR   >Options0331,#$80,L2DB6A                 ; bit 7: A/C pressure sensor fitted, not a switch (AcPressureSensor): idle A/C steps, clutch, cut and fan
        LDAA    >AcSensorRaw,Z
        CMPA    >AcSensorRawHigh
        BHI     L2DB6A
        CMPA    >AcSensorRawLow
        BHI     L2DB8E
L2DB6A:
        BRSET   >Options0331,#$40,L2DB86                 ; bit 6: A/C detection variant (EquipmentDetect, AcClutchControl, FanRelayControl)
        BRCLR   >Options0331,#$20,L2DB7E                 ; bit 5: A/C detection variant (EquipmentDetect, AcClutchControl)
        BRCLR   >SwitchInputs2,Z,#$80,L2DBA4             ; bit 7: A/C request switch (AcClutchControl, EquipmentDetect)
        BRA     L2DB8E
L2DB7E:
        BRSET   >SwitchInputs2,Z,#$80,L2DBA4             ; bit 7: A/C request switch (AcClutchControl, EquipmentDetect)
        BRA     L2DB8E
L2DB86:
        BRCLR   >AcFlags,Z,#$08,L2DBA4                   ; bit 3: A/C request from the bus (message bit 0 in CcdReceive)
        BRA     L2DBA0
L2DB8E:
        LDAA    >AcPresentCounter,Z
        CMPA    >AcPresentCount
        BCC     L2DBA0
        INCA
        STAA    >AcPresentCounter,Z
        BRA     L2DBA8
L2DBA0:
        BSET    <EquipmentFlags,Z,#$80                   ; bit 7: A/C fitted (EquipmentDetect)
L2DBA4:
        CLR     >AcPresentCounter,Z
L2DBA8:
        BRSET   >EquipmentFlags,Z,#$40,L2DBFA            ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
        BRCLR   >Options032D,#$20,L2DBCC                 ; bit 5: A/C clutch logic on (AcClutchLogicOn); also selects the switch-input map, the VSS constants and the speed control lamp
        BRCLR   >SwitchInputs2,Z,#$10,L2DBCC             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect)
        LDAA    >SpeedCtlPresentCounter,Z
        CMPA    >SpeedCtlPresentCount
        BCC     L2DBF6
        INCA
        STAA    >SpeedCtlPresentCounter,Z
        BRA     L2DBD0
L2DBCC:
        CLR     >SpeedCtlPresentCounter,Z
L2DBD0:
        BRSET   >SwitchInputs2,Z,#$08,L2DBF6             ; bit 3: speed control switch
        BRCLR   >SwitchInputs2,Z,#$04,L2DBF6             ; bit 2: speed control switch (set at reset)
        BRCLR   >Options0332,#$02,L2DBEA                 ; bit 1: speed control switch variant; also used by EquipmentDetect
        BRSET   >SwitchInputs2,Z,#$10,L2DBF6             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect)
        BRA     L2DBFA
L2DBEA:
        BRCLR   >Options0332,#$04,L2DBFA                 ; bit 2: speed control switch variant; also used by EquipmentDetect
        BRCLR   >SwitchInputs2,Z,#$11,L2DBFA             ; bit 4: speed control on/off switch (speed control code, lamp state, EquipmentDetect); bit 0: speed control switch
L2DBF6:
        BSET    <EquipmentFlags,Z,#$40                   ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
L2DBFA:
        BRSET   >EquipmentFlags,Z,#$04,L2DC34            ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
        BRCLR   >EngineStateFlags,Z,#$80,L2DC30          ; bit 7: engine turning: set at the first reference pulse, cleared when the engine stalls (CalcEngineRpm)
        BRSET   >IoInputs0,Z,#$08,L2DC30                 ; bit 3: key off, probably: the monitors skip while it is set and CheckPowerDown starts the power-down path
        LDAA    >BatteryVolts2,Z
        CMPA    #$C2
        BCS     L2DC30
        BRSET   >SwitchInputs2,Z,#$40,L2DC30             ; bit 6: power steering pressure switch: P0551 in PspSwitchMonitor, idle air and idle rpm adders (with EquipmentFlags bit 2)
        LDAA    >PspPresentCounter,Z
        CMPA    >PspPresentCount
        BCC     L2DC2C
        INCA
        STAA    >PspPresentCounter,Z
        BRA     L2DC34
L2DC2C:
        BSET    <EquipmentFlags,Z,#$04                   ; bit 2: power steering pressure switch fitted (calibration bit $0331.3, or EquipmentDetect)
L2DC30:
        CLR     >PspPresentCounter,Z
L2DC34:
        RTS

;---------------------------------------------------------------------------------------------------
; EquipmentProbe ($2DC36)
; Called from: CheckPowerDown
;---------------------------------------------------------------------------------------------------
EquipmentProbe:
        BRSET   >EquipmentFlags,Z,#$40,L2DC78            ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
        LDAA    >TFLG1,Z
        BITA    #$05
        BNE     L2DC78
        LDX     #$FF0C
        JSR     PowerInputHold
        BCS     L2DC78
        LDX     #$FF0C
        JSR     PowerInputHold
        BCS     L2DC78
        BSETW   >IoCtl12,Z,#$0080
        LDX     #$7F86
        JSR     PowerInputHold
        BCS     L2DC72
        BRCLR   >IoCtl12,Z,#$01,L2DC72
        BSET    <EquipmentFlags,Z,#$40                   ; bit 6: speed control fitted (EquipmentDetect, EquipmentProbe)
L2DC72:
        BCLRW   >IoCtl12,Z,#$0080
L2DC78:
        RTS

